-- Bone Valley — the real card, transcribed from the printed scorecard Kyle photographed
-- in the cart (2026-09-09; the two photos are the only source — the resort publishes no
-- Bone Valley PDF yet). Replaces the Phase 2 placeholder: 18 pars + men's stroke indexes,
-- all SEVEN tees (four base + the three combos), and 126 hole yardages.
--
-- Checked before seeding (scripts/gen — the same checks verify-card-data.py re-runs
-- against the DB): pars sum to the printed 36/36/72, stroke indexes are a 1–18
-- permutation, every base tee's yardages sum to its printed Out/In/Total, and every
-- combo's 18 derived yardages sum to its printed total. The combo row on this card is the
-- same ▲/▼ zigzag as the 2021 cards (▲ = back tee of the pair, ▼ = forward tee):
--   ▼▼▲▲▼▼▲▼▲ / ▼▲▲▼▲▲▲▼▼
-- Two Black back-nine cells were hard to read at the photo's resolution (16: 185 vs 195,
-- 17: 365 vs 355); 185/365 is the ONLY reading under which Black In = 3190 AND all three
-- combo totals reconcile, so that is what is seeded.
--
--   USGA (men)      rating / slope / yards
--   Green           74.7 / 134 / 7190     Green/Black   73.2 / 131 / 6875
--   Black           72.0 / 128 / 6600     Black/Silver  70.6 / 125 / 6320
--   Silver          69.4 / 120 / 6075     Silver/Gold   66.3 / 110 / 5430
--   Gold            63.3 / 105 / 4855
--   Par 36/36 = 72. Par 3s: holes 3, 7, 12, 16 (four — same as Red and Blue).
--
-- Tee stable-UUID scheme (same as the other courses): bbbb0004-0000-4000-8000-00000000000T
--   T = 1 Green, 2 Black, 3 Silver, 4 Gold, 5 Green/Black, 6 Black/Silver, 7 Silver/Gold.
--
-- The card is the authority here, so the tee and yardage upserts DO UPDATE on conflict
-- (the placeholder Green tee and its 18 null-yardage rows already exist), unlike the
-- DO NOTHING of the other seeds. Idempotent: re-running lands on the same values.

-- ─── Course ──────────────────────────────────────────────────────────────────
update public.courses
   set year_opened = 2026,
       description = 'David McLay Kidd''s 2026 course, the resort''s fourth: par 72 across the old Bone Valley phosphate ground, all sandy soil played as waste area.'
 where id = 'c0000000-0000-4000-8000-000000000004';

-- ─── Holes: par + men's stroke index ─────────────────────────────────────────
update public.holes as h
   set par = v.par, stroke_index = v.stroke_index
  from (values
    (1, 4, 5),
    (2, 4, 7),
    (3, 3, 13),
    (4, 5, 9),
    (5, 4, 1),
    (6, 4, 17),
    (7, 3, 15),
    (8, 4, 3),
    (9, 5, 11),
    (10, 4, 6),
    (11, 4, 12),
    (12, 3, 18),
    (13, 4, 2),
    (14, 5, 14),
    (15, 4, 16),
    (16, 3, 10),
    (17, 4, 4),
    (18, 5, 8)
  ) as v(hole_number, par, stroke_index)
 where h.course_id = 'c0000000-0000-4000-8000-000000000004' and h.hole_number = v.hole_number;

-- ─── Tees (four base + three combos) ─────────────────────────────────────────
insert into public.tees (id, course_id, name, rating, slope, par, total_yardage) values
  ('bbbb0004-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000004', 'Green',        74.7, 134, 72, 7190),
  ('bbbb0004-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000004', 'Black',        72.0, 128, 72, 6600),
  ('bbbb0004-0000-4000-8000-000000000003', 'c0000000-0000-4000-8000-000000000004', 'Silver',       69.4, 120, 72, 6075),
  ('bbbb0004-0000-4000-8000-000000000004', 'c0000000-0000-4000-8000-000000000004', 'Gold',         63.3, 105, 72, 4855),
  ('bbbb0004-0000-4000-8000-000000000005', 'c0000000-0000-4000-8000-000000000004', 'Green/Black',  73.2, 131, 72, 6875),
  ('bbbb0004-0000-4000-8000-000000000006', 'c0000000-0000-4000-8000-000000000004', 'Black/Silver', 70.6, 125, 72, 6320),
  ('bbbb0004-0000-4000-8000-000000000007', 'c0000000-0000-4000-8000-000000000004', 'Silver/Gold',  66.3, 110, 72, 5430)
on conflict (id) do update
   set name = excluded.name, rating = excluded.rating, slope = excluded.slope,
       par = excluded.par, total_yardage = excluded.total_yardage;

