-- ─── Publish ─────────────────────────────────────────────────────────────────
-- Only rpc_validate_and_publish_course may clear the placeholder flag from the app, and
-- it needs a session. A seed can't mint one, so this block re-runs the RPC's exact
-- checks and flips the flag only when every one of them passes — a partial card raises
-- and the migration fails loudly rather than publishing quietly-wrong data.
do $$
declare
  v_course constant uuid := 'c0000000-0000-4000-8000-000000000004';
  v_bad    int;
  v_si_ok  boolean;
begin
  select count(*) into v_bad from public.holes h
   where h.course_id = v_course and (h.par is null or h.stroke_index is null);
  if v_bad > 0 then raise exception 'Bone Valley seed: % hole(s) incomplete', v_bad; end if;

  select count(distinct h.stroke_index) = 18 and min(h.stroke_index) = 1 and max(h.stroke_index) = 18
    into v_si_ok from public.holes h where h.course_id = v_course;
  if not v_si_ok then raise exception 'Bone Valley seed: stroke indexes are not a 1–18 permutation'; end if;

  select count(*) into v_bad from public.tees t
   where t.course_id = v_course and (t.rating is null or t.slope is null);
  if v_bad > 0 then raise exception 'Bone Valley seed: % tee(s) lack rating/slope', v_bad; end if;

  select count(*) into v_bad
    from public.tees t cross join public.holes h
    left join public.hole_yardages y on y.tee_id = t.id and y.hole_id = h.id
   where t.course_id = v_course and h.course_id = v_course and (y.yardage is null);
  if v_bad > 0 then raise exception 'Bone Valley seed: % hole yardage(s) missing', v_bad; end if;

  if (select count(*) from public.tees t where t.course_id = v_course) <> 7 then
    raise exception 'Bone Valley seed: expected 7 tees';
  end if;

  update public.courses set data_is_placeholder = false where id = v_course;
end $$;
